            situation: state.situation ?? null,
            inventory: getInventory(),
            facts: getFacts(),
            people: getPeople(),
            places: getPlaces(),
            objectives: exec.renderer.renderProgress(state),
            recent_history: state.shortHistory.slice(-5)
